og","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/498741/de-procedure.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/498741/de-procedure.html","sha256":"d80a449cb311f84ccb31894fcbc3bfa23d514d02c7e539c65f803525e41bb878","checkedAt":"2026-11-01T20:40:43.747Z","fact":"Paperback ISBN 9789403134833 verschijningsdatum 11/07/2024 NUR 301 Literaire roman, novelle imprint De Bezige Bij uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sourceAuthors":"Harry Mulisch"},{"url":"https://metadata.isbn.nl/498741/de-procedure.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789023463825","key":{"isbn_13":"9789023463825"},"before":null,"after":{"work_id":1012,"title":"Nooit meer slapen","language":"nld","isbn_13":"9789023463825","isbn_10":null,"open_library_edition_id":null,"publisher":"Bezige Bij b.v., Uitgeverij De"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789023463825","key":{"edition_id":"@edition:9789023463825"},"before":null,"after":{"edition_id":"@edition:9789023463825","work_id":1012,"bound_author_id":637,"bound_title":"Nooit meer slapen","bound_language":"nld","bound_isbn13":"9789023463825","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000244081_Nooit_meer_slapen_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/138916/nooit-meer-slapen.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/138916/nooit-meer-slapen.html","sha256":"97e9320b7b98e8f8c88eb7c27a07a200deb625b08bc27cef0414d07f93e92ff3","checkedAt":"202