e geboortedorp. Zijn aankomst valt samen met onverklaarbare incidenten, die de dorpsgemeenschap beroeren. Veel later vertelt zijn broer Noël aan een voormalige politiecommissaris over die periode. Via zijn terugblik worden de geruchten rond René verbonden met vragen over schuld, liefde en wat mensen van het verleden willen weten.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/79915/de-geruchten.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/79915/de-geruchten.html","sha256":"a12acbef4ea35a45aca4401ff8be5590576ebfc51a39ee6d829204a051432cd0","checkedAt":"2026-11-01T20:40:48.155Z","fact":"Paperback ISBN 9789403108209 verschijningsdatum 23/02/2018 NUR 301 Literaire roman, novelle uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sourceAuthors":"Hugo Claus"},{"url":"https://metadata.isbn.nl/79915/de-geruchten.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789403103600","key":{"isbn_13":"9789403103600"},"before":null,"after":{"work_id":1023,"title":"De Verwondering","language":"nld","isbn_13":"9789403103600","isbn_10":null,"open_library_edition_id":null,"publisher":"Bezige Bij b.v., Uitgeverij De"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403103600","key":{"edition_id":"@edition:9789403103600"},"before":null,"after":{"edition_id":"@edition:9789403103600","work_id":1023,"bound_author_id":639,"bound_title":"De Verwondering","bound_language":"nld","bound_isbn13":"9789403103600","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000573564_De_Verwondering_2_710_130_0_0.jpg","card_cover_url":null,"evidence_url":"