ichter Charles van Orléans tijdens de strijd tussen vorstenhuizen en de oorlog met Engeland. Familiebelangen, politieke macht en persoonlijke verlangens raken verstrengeld in zijn leven. Ook zijn langdurige gevangenschap krijgt daarin een plaats. Rond zijn geschiedenis ontvouwt zich een wereld van hofleven, oorlog en poëzie, waarin een individu zich moet verhouden tot gebeurtenissen die hij maar beperkt kan sturen.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/39157/het-woud-der-verwachting.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/39157/het-woud-der-verwachting.html","sha256":"536dd8581035c465fba750e19d7d0e92b09c6dbeb4b98bbbca1fa8da4d935504","checkedAt":"2026-11-01T20:40:54.759Z","fact":"Hardback ISBN 9789021434223 verschijningsdatum 31/01/2008 NUR 301 Literaire roman, novelle uitgever Singel Uitgeverijen taal Nederlands","sourceAuthors":"Hella S. Haasse , Hella Haasse"},{"url":"https://metadata.isbn.nl/39157/het-woud-der-verwachting.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789021450759","key":{"isbn_13":"9789021450759"},"before":null,"after":{"work_id":1032,"title":"De scharlaken stad","language":"nld","isbn_13":"9789021450759","isbn_10":null,"open_library_edition_id":null,"publisher":"Querido"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789021450759","key":{"edition_id":"@edition:9789021450759"},"before":null,"after":{"edition_id":"@edition:9789021450759","work_id":1032,"bound_author_id":641,"bound_title":"De scharlaken stad","bound_language":"nld","bound_isbn13":"9789021450759","format":"paperback","cover_url":"https